import styles from "./InfoPanel.module.css";

export const InfoPanel = () => {
  return (
    <div className={styles.card}>
      <h3 className={styles.title}>Информационные сообщения</h3>

      <div className={styles.message}>
        <strong>Telegram Bot временно недоступен</strong>
        <p>
          Проводится обновление, бот возобновит работу в штатном режиме
          до 15:00
        </p>
      </div>
    </div>
  );
};
